// Alerta de coletor parado. Nasceu em 25/07/2026, depois de o coletor do
// Mercado Livre ficar 37 HORAS morto sem ninguem notar.
//
// LIMIAR = 18h, e o numero tem motivo. Amazon e YouTube coletam a 12/12h,
// entao a idade da ultima coleta deles oscila naturalmente ate 12h. Um limiar
// de 12h dispararia em TODO ciclo normal, e alerta que grita todo dia vira
// ruido que se aprende a ignorar -- mesmo efeito de nao ter alerta nenhum.
// 18h da 6h de folga e teria pego o ML no mesmo dia.
//
// ESTE NO SEMPRE DEVOLVE UM ITEM, mesmo com tudo saudavel -- e isso e desenho,
// nao sobra. A primeira versao devolvia [] quando estava tudo bem, e a execucao
// aberta mostrava "0 itens", o que parecia defeito. E parecia com razao:
// um monitor que nao mostra nada quando esta bem e
// indistinguivel de um monitor morto -- que e EXATAMENTE a falha silenciosa
// que este alerta existe para evitar. Agora toda execucao mostra o que leu,
// fonte por fonte, com idade em horas; quem decide enviar e o Filtro seguinte.
//
// *** 28/07/2026 -- O MERCADO LIVRE VOLTOU PARA A CONTA (5 de 5 monitoradas).
// Ele estava com monitorar:false desde 25/07 porque a fonte tinha fechado as
// rotas ao cracha honesto e o coletor fora despublicado; monitorar uma parada
// conhecida faria o alerta gritar todo dia. Em 28/07 a fonte REABRIU -- medido
// do mesmo servidor, mesma URL e mesmo metodo de 25/07: 517.012 bytes, 162 IDs
// MLB e 301 precos ao EnxameBot, contra 133.957 bytes e ZERO produtos cinco
// dias antes. O coletor foi republicado e voltou a rodar 6/6h.
// SE ESTE FLAG TIVESSE FICADO EM FALSE, o ML estaria no ar E FORA DA VIGILANCIA
// -- a mesma falha silenciosa de 37 horas que este workflow existe para impedir,
// so que desta vez por descuido nosso, e nao por falta de ferramenta.
//
// *** 06/10/2026 -- O MERCADO LIVRE SAIU DA CONTA DE NOVO (4 de 5 monitoradas).
// A fonte passou a pedir verificacao de conta (CAPTCHA) ao cracha honesto; o enxame-api
// devolve 451 e o coletor foi despublicado. Quem vigia a volta e a Sonda de Reabertura
// (8tJHu2GraKa3pnTU), a cada 3h, e a mensagem dela manda voltar este flag para true.
// A LICAO DE 28/07 VALE INTEIRA: coletor republicado com o flag em false fica no ar
// E FORA DA VIGILANCIA.
//
// *** 12/10/2026 -- O ML SAIU DA CONTA OUTRA VEZ, AGORA COM O COLETOR PUBLICADO.
// Em 10/10 a sonda viu uma janela aberta, o coletor foi republicado e este flag
// voltou a true; a fonte fechou em menos de 3h, e de 11/10 00:00 a 12/10 00:00 BRT as
// cinco rodadas levaram 451. O coletor fica no ar ate o fim do TCC e grava quando a fonte
// servir; este alerta avisava de 3/3h sobre a mesma parada. O preco declarado: enquanto
// este flag estiver false, uma falha do ML de OUTRO tipo tambem nao avisa. Quando o ML
// voltar a gravar, o flag volta a true no mesmo movimento.
//
// *** 02/11/2026 -- O GOOGLE SUGGEST SAIU DA CONTA (3 de 5 monitoradas), e desta vez o
// coletor foi DESPUBLICADO junto: o Suggest nao carrega volume
// (medido em 01/09) e saiu da analise, da Silver em diante. Sem este flag em false, a
// tabela dele ficaria parada na rodada de 02/11 00:00 BRT e o alerta gritaria em 18h.
// Se o coletor for republicado um dia, o flag volta a true NO MESMO MOVIMENTO (licao de 28/07).
const NL = String.fromCharCode(10);
const LIMITE_H = 18;
const FONTES = [
  { nome: 'Google Suggest', no: 'Ler Suggest', agenda: '6/6h', monitorar: false,
    motivo: 'desde 02/11/2026: o Suggest saiu do projeto (nao carrega volume; a busca do trabalho e o Google Trends) e o coletor foi despublicado; a ultima rodada gravada e a de 02/11 00:00 BRT' },
  { nome: 'YouTube', no: 'Ler YouTube', agenda: '12/12h', monitorar: true },
  { nome: 'Shopee', no: 'Ler Shopee', agenda: '6/6h', monitorar: true },
  { nome: 'Amazon', no: 'Ler Amazon', agenda: '12/12h', monitorar: true },
  { nome: 'Mercado Livre', no: 'Ler ML', agenda: '6/6h', monitorar: false,
    motivo: 'desde 12/10/2026: o coletor segue publicado e grava quando a fonte servir, mas ela pede verificacao de conta (CAPTCHA, HTTP 451) desde 06/10; avisar de 3/3h sobre a parada conhecida virou ruido' }
];
const agora = Date.now();
const paradas = [];
const situacao = [];
for (const f of FONTES) {
  let ts = null;
  try { ts = ($(f.no).first() || {}).json.coletado_em || null; } catch (e) { ts = null; }
  const idadeH = ts ? (agora - new Date(ts).getTime()) / 3600000 : null;
  const reg = {
    fonte: f.nome, agenda: f.agenda, ultima_coleta: ts,
    idade_horas: idadeH === null ? null : Math.round(idadeH * 10) / 10,
    monitorada: f.monitorar
  };
  if (!f.monitorar) { reg.estado = 'fora da conta'; reg.motivo = f.motivo; situacao.push(reg); continue; }
  reg.parada = idadeH === null || idadeH > LIMITE_H;
  reg.estado = reg.parada ? 'PARADA' : 'ok';
  if (reg.parada) paradas.push(reg);
  situacao.push(reg);
}
let txt = '';
if (paradas.length > 0) {
  txt = '*ENXAME - coletor parado*' + NL + NL;
  for (const p of paradas) {
    const quando = p.ultima_coleta ? p.ultima_coleta.slice(0, 16).replace('T', ' ') + ' UTC' : 'nunca';
    const quanto = p.idade_horas === null ? 'sem nenhuma coleta' : p.idade_horas + 'h atras';
    txt += '- ' + p.fonte + ' (' + p.agenda + '): ultima em ' + quando + ', ' + quanto + NL;
  }
  txt += NL + 'Limiar: ' + LIMITE_H + 'h. Verificado em ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC.' + NL;
  const fora = FONTES.filter(function (f) { return !f.monitorar; });
  if (fora.length === 0) { txt += 'As ' + FONTES.length + ' fontes estao na conta.'; }
  else { txt += 'Fora da conta: ' + fora.map(function (f) { return f.nome; }) + ' (ver o motivo na execucao).'; }
}
return [{ json: {
  alertar: paradas.length > 0,
  resumo: paradas.length === 0 ? 'tudo ok, nada a enviar' : paradas.length + ' fonte(s) parada(s)',
  limite_horas: LIMITE_H,
  fontes_monitoradas: FONTES.filter(function (f) { return f.monitorar; }).length,
  verificado_em: new Date().toISOString(),
  situacao: situacao,
  mensagem: txt
} }];
